import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,p})=>{let q=p[0]/100,start=[[-1,-.3,0],[-.7,-.3,0],[-1,.4,0],[-.7,.4,0],[.8,-.2,0],[.8,.2,0]],end=[[-1,.3,0],[-.2,.3,0],[.2,.3,0],[1,.3,0],[-.6,0,0],[.6,0,0]];for(let i=0;i<6;i++){let pos=start[i].map((v,j)=>v+(end[i][j]-v)*q);g.sphere(...pos,i<4?.1:.17,i<4?C.white:C.green)}g.text(0,-.9,0,'2H₂ + O₂ → 2H₂O');g.bars({title:b('Mass before and after','पहले और बाद का द्रव्यमान'),max:36,items:[{label:b('Before','पहले'),value:36,color:C.gold,unit:'u'},{label:b('After','बाद'),value:36,color:C.green,unit:'u'}]});return[read('H atoms conserved','H परमाणु संरक्षित',4),read('O atoms conserved','O परमाणु संरक्षित',2),read('Total mass','कुल द्रव्यमान',36,'u')];};
